        # representable without real per-player targeting. "target player"
        # IS a real target though — reuses p_gain_life/p_sacrifice's
        # {'filter': 'player'} target-tuple pipeline (converter.go lifts
        # ability.Target into SpellTargetType; the Engine's existing
        # targeted-draw resolution reads the chosen player instead of
        # defaulting to the ability's controller).
        n = _amt(args.get('amount'))
        who = (args.get('who') or '').strip()
        if n is None: return None
        if who in ('each opponent', 'target opponent'):
            return ('draw', {'amount': n, 'target': 'opponent'}, None)
        if who == 'target player':
            return ('draw', {'amount': n}, {'filter': 'player'})
        return None
>>>END
